-- YeOldeUIBar Class
YeOldeUIBar = ZO_InitializingObject:Subclass()

function YeOldeUIBar:Initialize(name)
	self.SV = YeOldeInfos.SV.Bars[name]
	local anchor = self.SV.Anchor

	self.name = name
	self.uiName = UI_BAR_PREFIX .. name
	self.hideIfEmpty = false
	self.blocs = {}

	--Create the control
	self.control = _G[self.uiName] or WINDOW_MANAGER:CreateTopLevelWindow(self.uiName)
	self.control:SetClampedToScreen(true)
	self.control:SetDrawTier(DT_HIGH)
	self.control:ClearAnchors()
	self.control:SetAnchor(anchor[1], GuiRoot, anchor[2], anchor[3], anchor[4])
	self.control:SetResizeToFitDescendents(true)
	self.control:SetHidden(not self.SV.Enabled)
	self.control:SetMouseEnabled(true)
	
	-- Mouse drag to move when holding Shift
	self.control:SetHandler("OnMouseDown", function(ctrl, button)
		if button == MOUSE_BUTTON_INDEX_LEFT and IsShiftKeyDown() then
			self.control:SetMovable(true)
			self.control:StartMoving()
		end
	end)
	self.control:SetHandler("OnMouseUp", function(ctrl, button)
		if button == MOUSE_BUTTON_INDEX_LEFT then
			self.control:StopMovingOrResizing()
			self.control:SetMovable(false)
		end
	end)

	self.control:SetHandler("OnMoveStop", function(ctrl)
		local isValidAnchor, point, _, relativePoint, offsetX, offsetY = ctrl:GetAnchor()
		if isValidAnchor then
			self.SV.Anchor = { point, relativePoint, offsetX, offsetY }
		end
	end)
	self.nextBlocAnchor = self.control
	self.fragment = ZO_SimpleSceneFragment:New(self.control)

	-- Initialize scene tables
	self.menuScenes = {
		SCENE_MANAGER:GetScene("inventory"),
		SCENE_MANAGER:GetScene("bank"),
		SCENE_MANAGER:GetScene("guildBank"),
		SCENE_MANAGER:GetScene("houseBank"),
		SCENE_MANAGER:GetScene("skills"),
		SCENE_MANAGER:GetScene("achievements"),
		SCENE_MANAGER:GetScene("antiquityJournalKeyboard"),
		SCENE_MANAGER:GetScene("antiquityLoreKeyboard"),
		WORLD_MAP_SCENE,
		STATS_SCENE,
		QUEST_JOURNAL_SCENE,
		PLAYER_SUBMENU_SCENE,
		KEYBOARD_GROUP_MENU_SCENE, -- BUG-3: doublon supprimé
		CAMPAIGN_OVERVIEW_SCENE,
		CAMPAIGN_BROWSER_SCENE,
		LEADERBOARDS_SCENE,
		COMPANION_CHARACTER_KEYBOARD_SCENE,
		COMPANION_SKILLS_KEYBOARD_SCENE,
		DAILY_LOGIN_REWARDS_KEYBOARD_SCENE,
		GAME_MENU_SCENE,
		NOTIFICATIONS_SCENE, -- BUG-3: doublon supprimé
		LORE_LIBRARY_SCENE,
		COLLECTIONS_BOOK_SCENE,
		GUILD_HOME_SCENE,
		GUILD_ROSTER_SCENE,
		GUILD_RANKS_SCENE,
		GUILD_CREATE_SCENE,
		GUILD_HISTORY_SCENE,
		GUILD_HERALDRY_SCENE,
		KEYBOARD_GUILD_RECRUITMENT_SCENE,
		KEYBOARD_GUILD_BROWSER_SCENE,
		KEYBOARD_LINK_GUILD_INFO_SCENE,
		TRADING_HOUSE_SCENE, -- BUG-3: doublon supprimé
		FRIENDS_LIST_SCENE,
		MAIL_INBOX_SCENE,
		MAIL_SEND_SCENE,
		ENCHANTING_SCENE,
		SMITHING_SCENE,
		ALCHEMY_SCENE,
		PROVISIONER_SCENE,
		SCENE_MANAGER:GetScene("gamepad_options_root"),
		SCENE_MANAGER:GetScene("gamepad_options_panel"),
	}
	self.gameScenes = {
		HUD_SCENE,
