	}
end

function YeOldeUIBar:SetbarVisibility(hideInMenu, hideInGame)
	-- PERF-1: Skip redundant scene updates if state hasn't changed
	if self._lastHideInMenu == hideInMenu and self._lastHideInGame == hideInGame then
		return
	end
	self._lastHideInMenu = hideInMenu
	self._lastHideInGame = hideInGame

	for _, scene in ipairs(self.menuScenes) do
		if hideInMenu then
			scene:RemoveFragment(self.fragment)
		else
			scene:AddFragment(self.fragment)
		end
	end
	for _, scene in ipairs(self.gameScenes) do
		if hideInGame then
			scene:RemoveFragment(self.fragment)
		else
			scene:AddFragment(self.fragment)
		end
	end
	if hideInMenu and hideInGame then
		self:SetHidden(true)
	end
end

--- Show/hide the stamp icon
---@param value boolean
function YeOldeUIBar:ShowStampIcon(value)
	for _, bloc in ipairs(self.blocs) do
		bloc:ShowStampIcon(value)
	end
end

function YeOldeUIBar:HaveStampIcon()
	local result = false
	for _, bloc in ipairs(self.blocs) do
		result = result or bloc:HaveStampIcon()
	end
	return result
end

function YeOldeUIBar:HaveText()
	local result = false
	for _, bloc in ipairs(self.blocs) do
		result = result or bloc:HaveText()
	end
	return result
end

function YeOldeUIBar:AddContentBloc(blocName, icon, text)
	local index = #self.blocs + 1
	self.blocs[index] = YeOldeUIBarContent:New(self.uiName .. "_" .. blocName, icon, text, self.nextBlocAnchor)
	self.blocs[index]:SetFont(self:GetFontFormatString())
	self.blocs[index]:SetIconSize(self.SV.IconHeight, self.SV.IconWidth, self.SV.IconScale)

	if self.nextBlocAnchor == self.control then
		self.blocs[index]:SetParentAnchor(LEFT, LEFT, 0, 0)
	end
	self.nextBlocAnchor = self.blocs[index]:GetAnchorHandler()
	return self.blocs[index]
end

function YeOldeUIBar:SetHandler(event, func)
	self.control:SetHandler(event, func)
end

