function YeOldeUIBar:SetHidden(value)
	self.control:SetHidden(value)
end

function YeOldeUIBar:GetLastVisibleBlocIndex()
	local result = 0
	for index, bloc in ipairs(self.blocs) do
		if bloc:IsVisible() and index > result then
			result = index
		end
	end
	return result
end

--- Show/hide a Content bloc.
---@param value boolean
function YeOldeUIBar:SetBlocHidden(bloc, value)
	local lastVisibleBlocIndex = self:GetLastVisibleBlocIndex()
	for index, tmpBloc in ipairs(self.blocs) do
		if bloc.name == tmpBloc.name then
			if index < lastVisibleBlocIndex then
				if value then
					self.blocs[index + 1]:SetParentAnchor(LEFT, LEFT, 0, 0)
				else
					self.blocs[index + 1]:SetParentAnchor(LEFT, RIGHT, 0, 0)
				end
			else
				if value or index == 1 or self.blocs[index - 1]:IsHidden() then
					self.blocs[index]:SetParentAnchor(LEFT, LEFT, 0, 0)
				else
					self.blocs[index]:SetParentAnchor(LEFT, RIGHT, 0, 0)
				end
			end
			bloc:SetHidden(value)
		end
	end
	self:SetHidden(self:IsAllBlocsHidden() and self.hideIfEmpty)
end

function YeOldeUIBar:IsAllBlocsHidden()
	for _, bloc in ipairs(self.blocs) do
		if not bloc.hidden then
			return false
		end
	end
	return true
end

function YeOldeUIBar:SetHideIfEmpty(value)
	self.hideIfEmpty = value
	self:SetHidden(self:IsAllBlocsHidden() and self.hideIfEmpty)
end

