--- Save anchor value (in SV)
function YeOldeUIBar:SaveAnchor()
	local isValidAnchor, point, _, relativePoint, offsetX, offsetY = self.control:GetAnchor()
	if isValidAnchor then
		self.SV.Anchor = { point, relativePoint, offsetX, offsetY }
	end
end

function YeOldeUIBar:GetFontFormatString()
	-- PERF-3: retourner le cache si disponible
	if self._fontFormatString then
		return self._fontFormatString
	end
	local face = self.SV.FontType
	local size = tonumber(self.SV.FontSize)
	local shadowStyle = "|soft-shadow-thick"
	if size <= 14 then
		shadowStyle = "|soft-shadow-thin"
	end
	local fontSizeString = string.format("$(KB_%d)", size)
	self._fontFormatString = ("$(%s)|%s|%s"):format(face, fontSizeString, shadowStyle)
	return self._fontFormatString
end

