-- Gamepad Directional Input Movement
------------------------------------

function YeOldeUIBar:StartGamepadMove()
	if not self.SV.Enabled or not YeOldeInfos.IsGamepadUIActive() then
		return
	end

	-- Save original anchors in case of cancellation
	local isValidAnchor, point, relativeTo, relativePoint, offsetX, offsetY = self.control:GetAnchor()
	if isValidAnchor then
		self.originalAnchor = { point, relativeTo, relativePoint, offsetX, offsetY }
	else
		self.originalAnchor = nil
	end

	-- Temporarily hide the Gamepad Options menu keybinds and directional input to steal focus
	if GAMEPAD_OPTIONS then
		if DIRECTIONAL_INPUT:IsListening(GAMEPAD_OPTIONS) then
			DIRECTIONAL_INPUT:Deactivate(GAMEPAD_OPTIONS)
			self._directionalInputDeactivated = true
		end
	end

	-- Push a clean keybind state to hide all standard keybinds easily without an action layer
	self._keybindStateIndex = KEYBIND_STRIP:PushKeybindGroupState()

	-- Setup Keybind Strip
	local function SwallowInput() return true end
	self.keybindStripDescriptor = {
		alignment = KEYBIND_STRIP_ALIGN_CENTER,
		{
			name = GetString(SI_SAVE),
			keybind = "UI_SHORTCUT_PRIMARY",
			callback = function()
				zo_callLater(function() self:StopGamepadMove(true) end, 10)
				return true -- Consume input safely
			end,
		},
		{
			name = GetString(SI_CANCEL),
			keybind = "UI_SHORTCUT_NEGATIVE",
			callback = function()
				zo_callLater(function() self:StopGamepadMove(false) end, 10)
				return true -- Consume input safely
			end,
		},
		-- Swallow standard navigation inputs so nothing else moves
		{ keybind = "UI_SHORTCUT_SECONDARY", callback = SwallowInput, ethereal = true },
		{ keybind = "UI_SHORTCUT_TERTIARY", callback = SwallowInput, ethereal = true },
		{ keybind = "UI_SHORTCUT_UP", callback = SwallowInput, ethereal = true },
		{ keybind = "UI_SHORTCUT_DOWN", callback = SwallowInput, ethereal = true },
		{ keybind = "UI_SHORTCUT_LEFT", callback = SwallowInput, ethereal = true },
		{ keybind = "UI_SHORTCUT_RIGHT", callback = SwallowInput, ethereal = true },
		{ keybind = "UI_SHORTCUT_LEFT_TRIGGER", callback = SwallowInput, ethereal = true },
		{ keybind = "UI_SHORTCUT_RIGHT_TRIGGER", callback = SwallowInput, ethereal = true },
		{ keybind = "UI_SHORTCUT_LEFT_SHOULDER", callback = SwallowInput, ethereal = true },
		{ keybind = "UI_SHORTCUT_RIGHT_SHOULDER", callback = SwallowInput, ethereal = true },
	}
	KEYBIND_STRIP:AddKeybindButtonGroup(self.keybindStripDescriptor, self._keybindStateIndex)

	-- Activate Input Engine
	DIRECTIONAL_INPUT:Activate(self, self.control)

	-- Detach fragment to guarantee visibility ignoring scene states
	self.detachedFromScene = SCENE_MANAGER:GetCurrentScene()
	if self.detachedFromScene then
		self.detachedFromScene:RemoveFragment(self.fragment)
	end

	-- Force the bar to be visible during movement
	self.wasHiddenBeforeMove = self.control:IsHidden()
	self.control:SetHidden(false)

	-- Update loop
	self.control:SetHandler("OnUpdate", function()
		self:UpdateDirectionalInput()
	end)
end

function YeOldeUIBar:StopGamepadMove(savePosition)
	DIRECTIONAL_INPUT:Deactivate(self)
	self.control:SetHandler("OnUpdate", nil)
	
	if self.keybindStripDescriptor then
		if self._keybindStateIndex then
			KEYBIND_STRIP:RemoveKeybindButtonGroup(self.keybindStripDescriptor, self._keybindStateIndex)
			KEYBIND_STRIP:PopKeybindGroupState()
			self._keybindStateIndex = nil
		else
			KEYBIND_STRIP:RemoveKeybindButtonGroup(self.keybindStripDescriptor)
		end
		self.keybindStripDescriptor = nil
	end

	-- Restore Gamepad Options menu navigation
	if GAMEPAD_OPTIONS and self._directionalInputDeactivated then
		DIRECTIONAL_INPUT:Activate(GAMEPAD_OPTIONS, GAMEPAD_OPTIONS.control)
		self._directionalInputDeactivated = false
	end

	if savePosition then
		self:SaveAnchor()
	else
		if self.originalAnchor then
			local pt, rt, rp, ox, oy = unpack(self.originalAnchor)
			self.control:ClearAnchors()
			self.control:SetAnchor(pt, rt, rp, ox, oy)
		end
	end

	-- Restore fragment and visibility state
	if self.detachedFromScene then
		self.detachedFromScene:AddFragment(self.fragment)
		self.detachedFromScene = nil
	end

	if self.wasHiddenBeforeMove ~= nil then
		self.control:SetHidden(self.wasHiddenBeforeMove)
		self.wasHiddenBeforeMove = nil
	end
end

function YeOldeUIBar:UpdateDirectionalInput()
	-- Do NOT pass ZO_DI_DPAD here because it uses IsKeyDown(), which throws an insecure code error for addons
	local dx, dy = DIRECTIONAL_INPUT:GetXY(ZO_DI_LEFT_STICK)
	
	if dx ~= 0 or dy ~= 0 then
		-- Target roughly 1% to 5% of screen real-estate per analogue tick.
		-- At 60FPS, 0.01 equates to crossing the screen relative to stick pressure in under 2 seconds.
		local speedX = GuiRoot:GetWidth() * 0.01
		local speedY = GuiRoot:GetHeight() * 0.01
		
		local moveX = dx * speedX
		local moveY = -dy * speedY -- ESO Y-axis is inverted for UI coordinates

		local left = self.control:GetLeft()
		local top = self.control:GetTop()

		self.control:ClearAnchors()
		self.control:SetAnchor(TOPLEFT, GuiRoot, TOPLEFT, left + moveX, top + moveY)
	end
end

