--- YeOldeUIBarContent Class
YeOldeUIBarContent = ZO_InitializingObject:Subclass()

function YeOldeUIBarContent:Initialize(blocName, icon, text, parent)
	self.name = blocName
	self.parent = parent
	self.hidden = false
	self.icon = icon
	self.iconHidden = false
	self.iconWidth = DEFAULT_ICON_SIZE
	self.iconHeight = DEFAULT_ICON_SIZE

	self.baseControl = WINDOW_MANAGER:CreateControl(blocName .. "_Base", parent, CT_CONTROL)
	self.baseControl:SetAnchor(LEFT, parent, RIGHT, 0, 0)
	self.baseControl:SetResizeToFitDescendents(true)

	self.baseControl:SetHandler("OnMouseDown", function(ctrl, button)
		if button == MOUSE_BUTTON_INDEX_LEFT and IsShiftKeyDown() then
			local tlw = ctrl:GetOwningWindow()
			if type(tlw.StartMoving) == "function" then
				tlw:SetMovable(true)
				tlw:StartMoving()
			end
		end
		if self.customMouseDown then
			self.customMouseDown(ctrl, button)
		end
	end)

	self.baseControl:SetHandler("OnMouseUp", function(ctrl, button)
		if button == MOUSE_BUTTON_INDEX_LEFT then
			local tlw = ctrl:GetOwningWindow()
			tlw:StopMovingOrResizing()
			if type(tlw.SetMovable) == "function" then
				tlw:SetMovable(false)
			end
		end
		if self.customMouseUp then
			self.customMouseUp(ctrl, button)
		end
	end)

	-- Icon
	self.iconHandler = WINDOW_MANAGER:CreateControl(blocName .. "_Icon", self.baseControl, CT_TEXTURE)
	self.iconHandler:SetAnchor(LEFT, self.baseControl, LEFT, BLOC_OFFSET, 0)
	self.iconHandler:SetTexture(icon)
	self.iconHandler:SetDimensions(self.iconWidth, self.iconHeight)

	-- Text
	local offsetX = ICON_TEXT_OFFSET

	if text == "" then
		offsetX = 0
	end

	self.textHandler = WINDOW_MANAGER:CreateControl(blocName .. "_Text", self.iconHandler, CT_LABEL)
	self.textHandler:SetAnchor(LEFT, self.iconHandler, RIGHT, offsetX, 0)
	self.textHandler:SetHorizontalAlignment(CENTER)
	self.textHandler:SetVerticalAlignment(CENTER)
	-- self.textHandler:SetFontHeight(self:GetFontHeight())
	self.textHandler:SetColor(1, 1, 1)
	self.textHandler:SetText(text)
end

--- Add a small stamp icon over the bloc icon
---@param icon table Icon path
---@param whereOnParent number Anchor position
---@param offsetX table
---@param offsetY table
---@param show table Anchor default visibility
function YeOldeUIBarContent:SetStampIcon(icon, width, height, whereOnParent, offsetX, offsetY, show)
	self.iconStamp = WINDOW_MANAGER:CreateControl(self.name .. "_IconStamp", self.iconHandler, CT_TEXTURE)
	self.iconStamp:SetTexture(icon)
	self.iconStamp:SetDimensions(width, height)
	self.iconStamp:SetAnchor(whereOnParent, self.iconHandler, whereOnParent, offsetX, offsetY)

	if show == nil then -- BUG-4: condition inversée corrigée
		show = true
	end
	self:ShowStampIcon(show)
end

function YeOldeUIBarContent:HaveStampIcon()
	return self.iconStamp ~= nil
end

function YeOldeUIBarContent:SetStampIconColor(r, g, b, a)
	if self.iconStamp ~= nil then
		self.iconStamp:SetColor(r, g, b, a)
	end
end

function YeOldeUIBarContent:HaveText()
	local text = self.textHandler:GetText()
	return (text ~= nil and text ~= "")
end

--- Show/hide the stamp icon
---@param value boolean
function YeOldeUIBarContent:ShowStampIcon(value)
	if self.iconStamp ~= nil then
		self.iconStamp:SetHidden(not value)
	end
end

function YeOldeUIBarContent:SetParentAnchor(whereOnMe, whereOnParent, offsetX, offsetY)
	self.baseControl:ClearAnchors()
	self.baseControl:SetAnchor(whereOnMe, self.parent, whereOnParent, offsetX, offsetY)
end

function YeOldeUIBarContent:GetAnchorHandler()
	return self.baseControl
end

function YeOldeUIBarContent:SetHandler(event, func)
	-- CT_TEXTURE (iconHandler) doesn't support mouse events in ESO.
	-- Route handlers through baseControl (CT_CONTROL) which covers the full bloc area.
	if event == "OnMouseDown" then
		self.customMouseDown = func
	elseif event == "OnMouseUp" then
		self.customMouseUp = func
	else
		self.baseControl:SetHandler(event, func)
	end
end

function YeOldeUIBarContent:GetWidth()
	-- PERF-4: éviter l'appel double à GetText()
	local text = self.textHandler:GetText()
	local width = BLOC_OFFSET + self.iconHandler:GetWidth()
	if text ~= nil and text ~= "" then
		width = width + self.textHandler:GetWidth() + ICON_TEXT_OFFSET
	end
	return width
end

function YeOldeUIBarContent:UpdateBaseWidth()
	-- PERF-4: éviter l'appel double à GetText()
	local text = self.textHandler:GetText()
	local width = BLOC_OFFSET + self.iconHandler:GetWidth()
	if text ~= nil and text ~= "" then
		width = width + self.textHandler:GetWidth() + ICON_TEXT_OFFSET
	end
	self.baseControl:SetWidth(width)
end

function YeOldeUIBarContent:ShowIcon(value)
	if self.iconHandler ~= nil then
		if value and self.iconHidden then
			self.iconHandler:SetTexture(self.icon)
			self.iconHandler:SetDimensions(self.iconWidth, self.iconHeight)
			self.iconHidden = false
			return
		end
		if not value and not self.iconHidden then
			self.iconHandler:SetTexture(BLANK_TEXTURE)
			self.iconHandler:SetDimensions(0, 0)
			self.iconHidden = true
		end
		self:UpdateBaseWidth()
	end
end

function YeOldeUIBarContent:SetIcon(icon, width, height) -- BUG-5: ordre des paramètres corrigé (width, height)
	self.icon = icon
	self.iconWidth = width
	self.iconHeight = height
	self.iconHandler:SetTexture(icon)
	self.iconHandler:SetDimensions(width, height)
	self:UpdateBaseWidth()
end

function YeOldeUIBarContent:SetIconSize(height, width, scale)
	scale = scale or 1
	self.iconHandler:SetDimensions(height * scale, width * scale)
	local _, point, relativeTo, relativePoint, offsetX, offsetY = self.iconHandler:GetAnchor()
	self.iconHandler:SetAnchor(point, relativeTo, relativePoint, offsetX, offsetY)
	self:UpdateBaseWidth()
end

function YeOldeUIBarContent:SetMouseEnabled(isEnabled)
	self.baseControl:SetMouseEnabled(isEnabled)
	self.iconHandler:SetMouseEnabled(isEnabled)
	self.textHandler:SetMouseEnabled(isEnabled)
end

function YeOldeUIBarContent:SetIconColor(r, g, b)
	self.iconHandler:SetColor(r, g, b)
end

function YeOldeUIBarContent:SetTextColor(r, g, b)
	self.textHandler:SetColor(r, g, b)
end

function YeOldeUIBarContent:SetTextAlpha(value)
	self.textHandler:SetAlpha(value)
end

function YeOldeUIBarContent:SetHidden(value)
	self.textHandler:SetHidden(value)
	self.iconHandler:SetHidden(value)
	self.hidden = value
end

function YeOldeUIBarContent:IsHidden()
	return self.hidden
end

function YeOldeUIBarContent:IsVisible()
	return not self.hidden
end

function YeOldeUIBarContent:SetText(text)
	self.textHandler:SetText(text)

	local offsetX = ICON_TEXT_OFFSET
	if text == "" then
		offsetX = 0
	end

	local isValidAnchor, point, relativeTo, relativePoint, _, _, _ = self.textHandler:GetAnchor(0)
	if isValidAnchor then
		self.textHandler:SetAnchor(point, relativeTo, relativePoint, offsetX, 0)
	end
	self:UpdateBaseWidth()
end

--- @param font string Font name from defaultfontdefs_keyboard.xml
function YeOldeUIBarContent:SetFont(font)
	--d("YeOldeUIBarContent:SetFont: "..font)
	self.textHandler:SetFont(font)
	--self.textHandler:SetFontHeight(self:GetFontHeight())
	self:UpdateBaseWidth()
end
